import { DatePipe } from '@angular/common';
import { Component, OnInit, computed, inject, signal } from '@angular/core';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { forkJoin } from 'rxjs';
import { SolicitudMock, SOLICITUDES_MOCK } from '../../../shared/mocks/solicitudes.mock';
import { Solicitud } from '../../../shared/models/solicitud.model';
import { Observacion, ObservacionTarget, NuevaObservacionData } from '../../../shared/models/observacion.model';
import { CampoObservableComponent } from '../../../shared/components/campo-observable/campo-observable.component';
import { ObservacionSidebarComponent } from '../../../shared/components/observacion-sidebar/observacion-sidebar.component';
import { ObservacionFormModalComponent } from '../../../shared/components/observacion-form-modal/observacion-form-modal.component';
import { ComiteSummaryComponent } from '../../../shared/components/comite-summary/comite-summary.component';
import { PdfViewerComponent } from '../../../shared/components/pdf-viewer/pdf-viewer.component';
import { ObservacionesService } from '../../../shared/services/observaciones.service';
import { SolicitudService } from '../../../shared/services/solicitud.service';
import { AuthService } from '../../../services/auth.service';
import { statusToClass } from '../../../shared/models/solicitud-status.util';
import { DocumentUploaderComponent } from '../../../shared/components/document-uploader/document-uploader';
import { DocumentoService } from '../../../services/documento.service';
import { ToastService } from '../../../shared/services/toast.service';
import { ToastContainerComponent } from '../../../shared/components/toast-container/toast-container.component';
import { extractErrorMessage } from '../../../shared/utils/error-utils';

@Component({
  selector: 'app-ver-solicitud',
  imports: [RouterLink, CampoObservableComponent, ObservacionSidebarComponent, ObservacionFormModalComponent, ComiteSummaryComponent, PdfViewerComponent, DocumentUploaderComponent, ToastContainerComponent, DatePipe],
  templateUrl: './ver-solicitud.component.html',
  styleUrl: './ver-solicitud.component.scss',
})
export class VerSolicitudComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private obsService = inject(ObservacionesService);
  private solicitudService = inject(SolicitudService);
  private auth = inject(AuthService);
  private documentoService = inject(DocumentoService);
  private toast = inject(ToastService);

  ngOnInit(): void {
    this.obsService.cargar(this.folio);
    this.cargarSolicitud();
  }

  readonly folio = this.route.snapshot.paramMap.get('id') ?? '—';
  readonly folioSignal = signal(this.folio);
  readonly origen = signal<'ejecutivo' | 'inversor'>(
    (this.route.snapshot.data['origen'] as 'ejecutivo' | 'inversor') ?? 'ejecutivo',
  );

  readonly solicitud = signal<SolicitudMock>(this.fallbackSolicitud());

  readonly selectedDocId = signal<number | null>(null);
  readonly selectedDocUrl = signal<string | null>(null);
  readonly selectedDocNombre = signal<string | null>(null);
  readonly mostrarVisor = signal(false);



  private cargarSolicitud(): void {
    this.solicitudService.getByFolio(this.folio).subscribe({
      next: (real) => this.solicitud.set(this.mapearSolicitud(real)),
      error: () => this.solicitud.set(this.fallbackSolicitud()),
    });
  }

  private mapearSolicitud(real: Solicitud): SolicitudMock {
    return {
      folio: real.folio,
      solicitante: real.solicitante,
      email: real.email,
      proyecto: real.proyecto,
      fechaRecepcion: real.fechaRecepcion,
      fechaSesion: real.fechaSesion,
      fechaResolucion: real.fechaResolucion,
      status: real.status,
      statusClass: real.statusClass,
      documentos: real.documentos,
      personalidadJuridica: real.personalidadJuridica as SolicitudMock['personalidadJuridica'],
      rfc: real.rfc,
      tieneRepresentanteLegal: real.tieneRepresentanteLegal ?? undefined,
      denominacionRazonSocial: real.denominacionRazonSocial ?? undefined,
      numeroFolio: real.numeroFolio ?? undefined,
      fechaOtorgamiento: real.fechaOtorgamiento ?? undefined,
      nombreRepresentante: real.nombreRepresentante ?? undefined,
      primerApellidoRepresentante: real.primerApellidoRepresentante ?? undefined,
      segundoApellidoRepresentante: real.segundoApellidoRepresentante ?? undefined,
    };
  }

  private fallbackSolicitud(): SolicitudMock {
    return SOLICITUDES_MOCK[this.folio] ?? {
      folio: this.folio,
      solicitante: 'Desconocido',
      email: '—',
      proyecto: 'Sin datos',
      fechaRecepcion: '—',
      fechaSesion: '—',
      fechaResolucion: '—',
      status: 'Sin datos',
      statusClass: 'bg-secondary',
      documentos: [],
    };
  }

  seleccionarDocumento(id: number, nombre?: string): void {
    const prevUrl = this.selectedDocUrl();
    this.selectedDocId.set(id);
    this.selectedDocNombre.set(nombre ?? null);
    this.selectedDocUrl.set(null);
    if (prevUrl) {
      URL.revokeObjectURL(prevUrl);
    }
    this.mostrarVisor.set(true);
  }

  verArchivoSubido(file: File): void {
    const prevUrl = this.selectedDocUrl();
    const url = URL.createObjectURL(file);
    this.selectedDocUrl.set(url);
    this.selectedDocNombre.set(file.name);
    if (prevUrl) {
      URL.revokeObjectURL(prevUrl);
    }
    this.selectedDocId.set(null);
    this.mostrarVisor.set(true);
  }

  cerrarVisor(): void {
    this.mostrarVisor.set(false);
    this.selectedDocId.set(null);
    this.selectedDocNombre.set(null);
    const url = this.selectedDocUrl();
    this.selectedDocUrl.set(null);
    if (url) {
      URL.revokeObjectURL(url);
    }
  }

  readonly modoEdicionParam = signal(
    this.route.snapshot.queryParamMap.get('mode') === 'edit',
  );

  readonly editMode = computed(
    () => this.origen() === 'inversor' && this.modoEdicionParam(),
  );

  readonly modoEvaluador = computed(
    () => this.origen() === 'ejecutivo' && !this.editMode(),
  );

  readonly puedeDesignarComite = computed(
    () => this.modoEvaluador() && this.solicitud().status === 'En Dictaminación',
  );

  readonly observaciones = computed<Observacion[]>(() =>
    this.obsService.observacionesDe(this.folio),
  );

  readonly statusOverride = signal<string | null>(null);
  readonly statusCalculado = computed(() => this.statusOverride() ?? this.solicitud().status);
  readonly statusClassCalculado = computed(() => statusToClass(this.statusCalculado()));
  readonly tieneObservacionesPendientes = computed(() =>
    this.observaciones().some((o) => o.status === 'pendiente'),
  );

  readonly puedeEnviarCorrecciones = computed(() => !this.tieneObservacionesPendientes());

  resaltado = signal<string | null>(null);

  modalAbierto = signal(false);
  modalTarget = signal<ObservacionTarget | null>(null);
  modalTargetLabel = signal('');
  readonly modalEditingObs = signal<Observacion | null>(null);

  readonly cambios = signal<Record<string, string>>({});

  readonly guardando = signal(false);

  readonly documentSlugs = computed(() =>
    Object.fromEntries(this.solicitud().documentos.map((d) => [d.id, this.slugify(d.nombreOriginal)])),
  );

  readonly FIELD_LABELS: Record<string, string> = {
    solicitante: 'Nombre completo',
    denominacionRazonSocial: 'Denominación o razón social',
    rfc: 'RFC',
    email: 'Correo electrónico',
    tieneRepresentanteLegal: '¿Cuenta con representante legal?',
    numeroFolio: 'Número o folio de la póliza o acta constitutiva',
    fechaOtorgamiento: 'Fecha de otorgamiento',
    nombreRepresentante: 'Nombre del representante',
    primerApellidoRepresentante: 'Primer apellido del representante',
    segundoApellidoRepresentante: 'Segundo apellido del representante',
    proyecto: 'Nombre del proyecto',
  };

  readonly SECTION_LABELS: Record<string, string> = {
    'info-general': 'Datos del inversionista',
    'detalles-inversion': 'Detalles de la inversión',
    fechas: 'Fechas',
    documentos: 'Documentos adjuntos',
    proyecto: 'Información del proyecto',
  };

  private readonly FIELD_MAP: Record<string, string> = {
    email: 'correo_electronico',
    solicitante: 'nombre_completo',
    proyecto: 'nombre_proyecto',
    denominacionRazonSocial: 'denominacion_razon_social',
    numeroFolio: 'numero_folio',
    fechaOtorgamiento: 'fecha_otorgamiento',
    nombreRepresentante: 'nombre_representante',
    primerApellidoRepresentante: 'primer_apellido_representante',
    segundoApellidoRepresentante: 'segundo_apellido_representante',
    rfc: 'rfc',
    tieneRepresentanteLegal: 'tiene_representante_legal',
  };

  private readonly FIELD_SECTION_MAP: Record<string, string> = {
    email: 'info-general',
    solicitante: 'info-general',
    proyecto: 'info-general',
    denominacionRazonSocial: 'info-general',
    numeroFolio: 'info-general',
    fechaOtorgamiento: 'info-general',
    nombreRepresentante: 'info-general',
    primerApellidoRepresentante: 'info-general',
    segundoApellidoRepresentante: 'info-general',
    rfc: 'info-general',
    tieneRepresentanteLegal: 'info-general',
  };

  observacionesParaCampo(fieldId: string): Observacion[] {
    return this.observaciones().filter(
      (o) => o.target.type === 'field' && o.target.fieldId === fieldId,
    );
  }

  observacionesParaSeccion(sectionId: string): Observacion[] {
    return this.observaciones().filter(
      (o) => o.target.type === 'section' && o.target.sectionId === sectionId,
    );
  }

  seccionTieneObsPendiente(sectionId: string): boolean {
    return this.observaciones().some(
      (o) =>
        o.target.type === 'section' &&
        o.target.sectionId === sectionId &&
        o.status === 'pendiente',
    );
  }

  documentoTieneObsPendiente(docId: number): boolean {
    return this.observaciones().some(
      (o) =>
        o.target.type === 'document' &&
        (o.target as { type: 'document'; documentId: number }).documentId === docId &&
        o.status === 'pendiente',
    );
  }

  observacionesParaDocumento(docId: number): Observacion[] {
    return this.observaciones().filter(
      (o) =>
        o.target.type === 'document' &&
        (o.target as { type: 'document'; documentId: number }).documentId === docId,
    );
  }

  campoEsEditable(fieldId: string, sectionId: string): boolean {
    return (
      this.editMode() &&
      (this.observacionesParaCampo(fieldId).some((o) => o.status === 'pendiente') ||
        this.seccionTieneObsPendiente(sectionId))
    );
  }

  slugify(s: string): string {
    return s
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
  }

  private getDocumentLabel(docId: number): string {
    const doc = this.solicitud().documentos.find((d) => d.id === docId);
    return doc ? `${doc.nombreOriginal} (${doc.tipoDocumento?.nombre ?? 'Documento'})` : `Documento #${docId}`;
  }

  toStringId(id: number): string {
    return String(id);
  }

  abrirModal(target: ObservacionTarget): void {
    this.modalTarget.set(target);
    switch (target.type) {
      case 'field':
        this.modalTargetLabel.set(this.FIELD_LABELS[target.fieldId] ?? target.fieldId);
        break;
      case 'section':
        this.modalTargetLabel.set(this.SECTION_LABELS[target.sectionId] ?? target.sectionId);
        break;
      case 'document':
        this.modalTargetLabel.set(this.getDocumentLabel(target.documentId));
        break;
    }
    this.modalAbierto.set(true);
  }

  cerrarModal(): void {
    this.modalAbierto.set(false);
    this.modalTarget.set(null);
    this.modalTargetLabel.set('');
    this.modalEditingObs.set(null);
  }

  onGuardarObservacion(data: NuevaObservacionData): void {
    const editingObs = this.modalEditingObs();
    if (editingObs) {
      this.obsService.editar(editingObs.id, { texto: data.texto }, this.folio).subscribe({
        next: () => {
          this.toast.success('Observación actualizada.');
          this.cerrarModal();
        },
        error: (err) => {
          this.toast.error(extractErrorMessage(err));
        },
      });
    } else {
      const evaluador = this.auth.currentUser()?.name ?? 'Evaluador';
      this.obsService.agregar(this.folio, { ...data, evaluador }).subscribe({
        next: (res) => {
          this.toast.success(res.message ?? 'Observación registrada correctamente.');
          this.statusOverride.set(res.status ?? 'Incompleta');
          this.cerrarModal();
        },
        error: (err) => {
          this.toast.error(extractErrorMessage(err));
        },
      });
    }
  }

  alIrA(target: ObservacionTarget): void {
    let id: string;
    switch (target.type) {
      case 'field':
        id = `field-${target.fieldId}`;
        this.resaltado.set(target.fieldId);
        break;
      case 'section':
        id = `section-${target.sectionId}`;
        this.resaltado.set(target.sectionId);
        break;
      case 'document':
        id = `documento-${this.documentSlugs()[target.documentId] ?? target.documentId}`;
        this.resaltado.set(String(target.documentId));
        break;
    }
    const el = document.getElementById(id);
    el?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    if (el) {
      const focusable = el.matches('input,textarea,button,select,a,[tabindex]')
        ? el
        : el.querySelector<HTMLElement>('input,textarea,button,select,a,[tabindex]');
      focusable?.focus({ preventScroll: true });
    }
    setTimeout(() => this.resaltado.set(null), 2000);
  }

  alCorregir(id: number): void {
    this.obsService.marcarCorregida(this.folio, id).subscribe({
      next: () => {
        this.toast.success('Observación marcada como corregida.');
        if (
          this.statusCalculado() === 'Incompleta' &&
          !this.tieneObservacionesPendientes()
        ) {
          const subsanar = this.modoEvaluador()
            ? this.obsService.subsanarTramites(this.folio)
            : this.obsService.enviarCorreccionesInversor(this.folio);
          subsanar.subscribe({
            next: () => {
              this.statusOverride.set('Subsanada');
            },
            error: (err) => {
              this.toast.error(extractErrorMessage(err));
            },
          });
        }
      },
      error: (err) => {
        this.toast.error(extractErrorMessage(err));
      },
    });
  }

  onNotificar(): void {
    this.obsService.enviarObservaciones(this.folio).subscribe({
      next: () => {
        this.toast.success('Se han notificado las observaciones pendientes al inversionista.');
        this.statusOverride.set('Incompleta');
      },
      error: (err) => {
        this.toast.error(extractErrorMessage(err));
      },
    });
  }

  onEditarObservacion(obs: Observacion): void {
    this.modalEditingObs.set(obs);
    this.modalTarget.set(obs.target);
    switch (obs.target.type) {
      case 'field':
        this.modalTargetLabel.set(this.FIELD_LABELS[obs.target.fieldId] ?? obs.target.fieldId);
        break;
      case 'section':
        this.modalTargetLabel.set(this.SECTION_LABELS[obs.target.sectionId] ?? obs.target.sectionId);
        break;
      case 'document':
        this.modalTargetLabel.set(this.getDocumentLabel(obs.target.documentId));
        break;
    }
    this.modalAbierto.set(true);
  }

  onEliminarObservacion(id: number): void {
    this.obsService.eliminar(this.folio, id).subscribe({
      next: () => {
        this.toast.success('Observación eliminada.');
      },
      error: (err) => {
        this.toast.error(extractErrorMessage(err));
      },
    });
  }

  onCampoCambiado(fieldId: string, valor: string): void {
    this.cambios.update((c) => ({ ...c, [fieldId]: valor }));
  }

  guardarCambios(): void {
    if (Object.keys(this.cambios()).length === 0) {
      this.toast.info('No hay cambios por guardar.');
      return;
    }
    this.guardando.set(true);
    const payload: Record<string, unknown> = {};
    for (const [fieldId, valor] of Object.entries(this.cambios())) {
      const backendKey = this.FIELD_MAP[fieldId];
      if (!backendKey) continue;
      if (fieldId === 'tieneRepresentanteLegal') {
        payload[backendKey] = valor === 'Sí' || valor === 'true';
      } else {
        payload[backendKey] = valor;
      }
    }
    const changedFieldIds = Object.keys(this.cambios());
    this.solicitudService.actualizarSolicitud(this.folio, payload).subscribe({
      next: () => {
        this.guardando.set(false);
        this.solicitud.update((s) => ({
          ...s,
          ...Object.fromEntries(
            Object.entries(this.cambios()).map(([fieldId, valor]) => [
              fieldId,
              fieldId === 'tieneRepresentanteLegal'
                ? valor === 'Sí' || valor === 'true'
                : valor,
            ]),
          ),
        }));
        this.cambios.set({});
        this.toast.success('Cambios guardados correctamente.');

        const sectionIds = new Set<string>();
        for (const fieldId of changedFieldIds) {
          this.observacionesParaCampo(fieldId)
            .filter((o) => o.status === 'pendiente')
            .map((o) => o.id)
            .forEach((id) => {
              this.obsService.marcarAtendida(this.folio, id).subscribe();
            });

          const sectionId = this.FIELD_SECTION_MAP[fieldId];
          if (sectionId) sectionIds.add(sectionId);
        }
        for (const sectionId of sectionIds) {
          this.observacionesParaSeccion(sectionId)
            .filter((o) => o.status === 'pendiente')
            .map((o) => o.id)
            .forEach((id) => {
              this.obsService.marcarAtendida(this.folio, id).subscribe();
            });
        }
      },
      error: (err) => {
        this.guardando.set(false);
        this.toast.error(extractErrorMessage(err));
      },
    });
  }

  onDocumentoReemplazado(docId?: number): void {
    const patchCalls: ReturnType<typeof this.obsService.marcarAtendida>[] = [];
    if (docId !== undefined) {
      this.observacionesParaDocumento(docId)
        .filter((o) => o.status === 'pendiente')
        .map((o) => o.id)
        .forEach((id) => {
          patchCalls.push(this.obsService.marcarAtendida(this.folio, id));
        });
      this.observacionesParaSeccion('documentos')
        .filter((o) => o.status === 'pendiente')
        .map((o) => o.id)
        .forEach((id) => {
          patchCalls.push(this.obsService.marcarAtendida(this.folio, id));
        });
    }
    if (patchCalls.length === 0) {
      this.toast.success('Documento reemplazado correctamente.');
      this.cargarSolicitud();
      return;
    }
    forkJoin(patchCalls).subscribe({
      next: () => {
        this.toast.success('Documento reemplazado correctamente.');
        this.cargarSolicitud();
        this.obsService.cargar(this.folio);
      },
      error: (err) => {
        this.toast.error(extractErrorMessage(err));
      },
    });
  }

  onEnviarCorreccionesInversor(): void {
    this.obsService.enviarCorreccionesInversor(this.folio).subscribe({
      next: () => {
        this.statusOverride.set('Subsanada');
        this.toast.success('Correcciones enviadas. La solicitud ha sido marcada como subsanada.');
      },
      error: (err) => {
        this.toast.error(extractErrorMessage(err));
      },
    });
  }
}
